final class Capacity {
    private final java.util.concurrent.atomic.AtomicInteger remaining;
    private final java.util.concurrent.CyclicBarrier firstReads;
    private final ThreadLocal<Boolean> firstRead = ThreadLocal.withInitial(() -> true);

    Capacity(int slots, int callers) {
        remaining = new java.util.concurrent.atomic.AtomicInteger(slots);
        firstReads = new java.util.concurrent.CyclicBarrier(callers);
    }

    int available() {
        int snapshot = remaining.get();
        if (firstRead.get()) {
            firstRead.set(false);
            try {
                firstReads.await(2, java.util.concurrent.TimeUnit.SECONDS);
            } catch (InterruptedException failure) {
                Thread.currentThread().interrupt();
                throw new IllegalStateException(failure);
            } catch (java.util.concurrent.BrokenBarrierException | java.util.concurrent.TimeoutException failure) {
                throw new IllegalStateException(failure);
            }
        }
        return snapshot;
    }

    boolean compareAndSet(int observed, int updated) {
        return remaining.compareAndSet(observed, updated);
    }

    void set(int updated) { remaining.set(updated); }
    int remaining() { return remaining.get(); }
}

